
module binary_to_gray(
    input [3:0] bin_in,
    output [3:0] gray_out
);

// MSB of gray code is same as MSB of binary code
assign gray_out[3] = bin_in[3];

// Other bits are generated by XORing adjacent bits in binary code
assign gray_out[2] = bin_in[2] ^ bin_in[3];
assign gray_out[1] = bin_in[1] ^ bin_in[2];
assign gray_out[0] = bin_in[0] ^ bin_in[1];

endmodule